import React, { useEffect } from 'react';
import ClientesCarrusel from '../components/ClientesCarrusel';
import { Link, useNavigate } from 'react-router-dom';
import '../styles/Inicio.css';

const Inicio = () => {
  const navigate = useNavigate();
  useEffect(() => {
  document.body.style.backgroundImage = "url('/fondo-naranja.png')";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundRepeat = "no-repeat";
    document.body.style.minHeight = "100vh";
    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundRepeat = "";
      document.body.style.minHeight = "";
    };
  }, []);
  return (
    <div className="inicio-container">
      <h1 className="inicio-title">PHG Soluciones Contables</h1>
      <p className="inicio-desc">Tu aliado en servicios contables, auditoría y asesoría financiera.</p>
      <nav className="inicio-nav">
        <Link to="/servicios">Servicios</Link>
        <Link to="/sobre-nosotros">Sobre Nosotros</Link>
        <Link to="/contacto">Contacto</Link>
        <Link to="/ubicacion-redes">Ubicación y Redes</Link>
      </nav>
    <img src="/logo.png" alt="PHG Soluciones Contables" className="inicio-logo" />
    {/* Botón 'Regresar' eliminado de Inicio */}
    <ClientesCarrusel />
    </div>
  );
};

export default Inicio;
